import React from 'react';
import './Navbar.css';

function Navbar() {
  return (
    <nav className="navbar">
      <div className="logo">TwoWheelers</div>
      <ul className="nav-links">
        <li>Home</li>
        <li>Sell Bike</li>
        <li>Login</li>
      </ul>
    </nav>
  );
}

export default Navbar;
